// ============================================
// ReviewPilot Lite - Phase 3
// FILTER REVIEWS (Cleaning Layer)
// Output  = kept (clean reviews)
// ============================================

const items = $input.all();

const MIN_WORDS = 15;
const MIN_CHARS = 80;

const spamPhrases = [
  'great product',
  'fast shipping',
  'good seller',
  'five stars',
  'as described',
  'highly recommend',
  'thank you',
  'nice item',
  'arrived quickly',
  'perfect seller'
];

const seenTexts = new Set();
const kept = [];
const removed = [];

for (const item of items) {
  const r = item.json;
  const text = (r.text || '').toString().trim();
  const rating = Number(r.rating);
  const words = text.split(/\s+/).filter(Boolean).length;

  let reason = null;

  // Rule 1: keep only 2, 3, 4-star reviews
  if (!rating || rating < 2 || rating > 4) {
    reason = 'rating_out_of_scope';
  }

  // Rule 2: remove low-effort reviews
  if (!reason && (words < MIN_WORDS || text.length < MIN_CHARS)) {
    reason = 'too_short_or_low_effort';
  }

  // Rule 3: remove spam-pattern reviews
  if (!reason) {
    const lower = text.toLowerCase();
    const spamScore = spamPhrases.filter(p => lower.includes(p)).length;
    if (spamScore >= 2) reason = 'spam_pattern';
  }

  // Rule 4: remove exact duplicates
  if (!reason) {
    const key = text.toLowerCase().replace(/\s+/g, ' ');
    if (seenTexts.has(key)) {
      reason = 'duplicate';
    } else {
      seenTexts.add(key);
    }
  }

  if (reason) {
    removed.push({
      json: {
        review_id: r.review_id,
        rating: rating,
        reason: reason,
        word_count: words,
        text_preview: text.slice(0, 60)
      }
    });
  } else {
    kept.push(item);
  }
}

// Output
// Quality gate: never continue with too few clean reviews
if (kept.length < 3) {
  throw new Error(
    'Quality gate failed: only ' + kept.length +
    ' clean reviews found (minimum 3). Check the product URL, platform, or scraper.'
  );
}

return kept;

// ============================================
// ReviewPilot Lite - Phase 4
// CREATE REVIEW BATCHES
// Splits clean reviews into small batches so the
// LLM gets focused, high-quality input.
// ============================================

const reviews = $input.all().map(item => item.json);

const batchSize = 5;
const batches = [];

for (let i = 0; i < reviews.length; i += batchSize) {
  batches.push(reviews.slice(i, i + batchSize));
}

return batches.map((batch, index) => ({
  json: {
    batch_number: index + 1,
    total_batches: batches.length,
    reviews: batch
  }
}));

// ============================================
// ReviewPilot Lite - Phase 4
// BUILD AI REQUEST (Groq via HTTP Request node)
// Assembles the request body so the HTTP node
// never has to deal with escaping or {{ }}.
// ============================================

const meta = $('Set Inputs').first().json;

const systemPrompt = `You are ReviewPilot, a product-intelligence analyst.

You will receive customer reviews (2-4 stars) for a competitor product.

Perform aspect-based sentiment analysis. Do not summarize generally.
Extract only information present in the reviews. Never invent anything.
Ignore shipping-only comments unless they reveal a product issue.
Never include reviewer personal data.

Identify product aspects (for example: zipper, straps, waterproofing, laptop sleeve, pockets, comfort, fabric, design, sizing) and the sentiment toward each.

Then produce exactly three lists:

- exploitable_weaknesses: features customers repeatedly complain about. These can be used against the competitor in ads and positioning.
- product_gaps: features customers explicitly ask for or imply are missing.
- table_stakes: features customers love or expect as a minimum standard to compete.

For each entry provide:
- name: short feature name
- insight: one clear business sentence
- mention_count: how many reviews in this batch mention it
- severity: low, medium, or high (omit for table_stakes)
- evidence_quotes: up to 2 short verbatim quotes, max 15 words each

Return ONLY valid JSON. No markdown. No explanations. Exact shape:

{
  "exploitable_weaknesses": [
    { "name": "", "insight": "", "mention_count": 0, "severity": "", "evidence_quotes": [] }
  ],
  "product_gaps": [
    { "name": "", "insight": "", "mention_count": 0, "severity": "", "evidence_quotes": [] }
  ],
  "table_stakes": [
    { "name": "", "insight": "", "mention_count": 0, "evidence_quotes": [] }
  ]
}`;

const userPrompt = `Competitor: ${meta.competitor_name}
Product URL: ${meta.product_url}
Batch ${$json.batch_number} of ${$json.total_batches}

Analyze these reviews:

${JSON.stringify($json.reviews)}`;

return {
  json: {
    requestBody: {
      model: 'openai/gpt-oss-120b',
      messages: [
        { role: 'system', content: systemPrompt },
        { role: 'user', content: userPrompt }
      ],
      temperature: 0
    }
  }
};

// ============================================
// ReviewPilot Lite - Phase 5 (Part 1)
// PARSE AI JSON
// Safely parses the AI text into JSON.
// Handles empty strings (rate limits) gracefully.
// ============================================

const aiJsonStr = $json.aiJson || "";

// If the AI returned empty (rate limit), return empty arrays
if (!aiJsonStr.trim()) {
  return { 
    json: { 
      exploitable_weaknesses: [], 
      product_gaps: [], 
      table_stakes: [], 
      _empty_batch: true 
    } 
  };
}

// Clean markdown fences if the AI added them
let cleanStr = aiJsonStr.replace(/^```json\s*/i, '').replace(/```$/g, '').trim();

// Extract just the JSON object if there's extra text
const firstBrace = cleanStr.indexOf('{');
const lastBrace = cleanStr.lastIndexOf('}');
if (firstBrace !== -1 && lastBrace !== -1) {
  cleanStr = cleanStr.slice(firstBrace, lastBrace + 1);
}

try {
  const parsed = JSON.parse(cleanStr);
  return { json: { ...parsed, _empty_batch: false } };
} catch (error) {
  // If JSON is totally broken, don't crash, just return empty
  return { 
    json: { 
      exploitable_weaknesses: [], 
      product_gaps: [], 
      table_stakes: [], 
      _parse_error: error.message 
    } 
  };
}

// ============================================
// ReviewPilot Lite - Phase 5 (Part 2)
// AGGREGATE INSIGHTS
// Merges all batches, sums mention counts,
// deduplicates features, and sorts by frequency.
// ============================================

const items = $input.all();

const merged = {
  exploitable_weaknesses: [],
  product_gaps: [],
  table_stakes: []
};

// Helper to normalize feature names for deduplication
function normalizeKey(text) {
  return (text || '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
}

function addItem(type, entry) {
  if (!entry || !entry.name) return;
  const key = normalizeKey(entry.name);

  // Check if we already have this feature from a previous batch
  let existing = merged[type].find(i => normalizeKey(i.name) === key);

  if (existing) {
    // Sum the mention counts
    existing.mention_count = (Number(existing.mention_count) || 0) + (Number(entry.mention_count) || 1);
    // Combine evidence quotes (max 5)
    existing.evidence_quotes = [
      ...new Set([...(existing.evidence_quotes || []), ...(entry.evidence_quotes || [])])
    ].slice(0, 5);
    // Escalate severity if needed
    if (entry.severity === 'high') existing.severity = 'high';
  } else {
    // Add as a new feature
    merged[type].push({
      name: entry.name,
      insight: entry.insight || '',
      mention_count: Number(entry.mention_count) || 1,
      severity: entry.severity || 'medium',
      evidence_quotes: (entry.evidence_quotes || []).slice(0, 5)
    });
  }
}

// Loop through all parsed batches
for (const item of items) {
  const data = item.json;

  // Skip empty or broken batches safely
  if (data._empty_batch || data._parse_error) continue;

  (data.exploitable_weaknesses || []).forEach(e => addItem('exploitable_weaknesses', e));
  (data.product_gaps || []).forEach(e => addItem('product_gaps', e));
  (data.table_stakes || []).forEach(e => addItem('table_stakes', e));
}

// Sort everything by mention_count (highest first)
merged.exploitable_weaknesses.sort((a, b) => b.mention_count - a.mention_count);
merged.product_gaps.sort((a, b) => b.mention_count - a.mention_count);
merged.table_stakes.sort((a, b) => b.mention_count - a.mention_count);

return [{ json: merged }];

// ============================================
// ReviewPilot Lite - Phase 6
// FORMAT OUTPUT ROWS
// Flattens the merged report into spreadsheet rows
// tagged by insight type + business action.
// ============================================

const data = $input.first().json;
const meta = $('Set Inputs').first().json;
const runId = new Date().toISOString().replace(/[:.]/g, '-');

const rows = [];

function addRows(type, list, actionPrefix) {
  for (const item of list || []) {
    rows.push({
      json: {
        Timestamp: new Date().toISOString(),
        RunID: runId,
        Competitor: meta.competitor_name,
        ProductURL: meta.product_url,
        Platform: meta.platform,
        InsightType: type,
        Feature: item.name,
        Insight: item.insight,
        MentionCount: item.mention_count,
        Severity: item.severity || '',
        Evidence: (item.evidence_quotes || []).join(' | '),
        RecommendedAction: actionPrefix + ' ' + (item.insight || '')
      }
    });
  }
}

addRows('Exploitable Weakness', data.exploitable_weaknesses, 'Use in ads and landing pages:');
addRows('Product Gap', data.product_gaps, 'Add to product roadmap:');
addRows('Table Stake', data.table_stakes, 'Must match or exceed:');

return rows;
